def apply_appearance(html: str, page: str) -> str:
    """Preserve page behavior while replacing its navigation and visual shell."""
    if page == "dashboard":
        html = re.sub(r'<nav class="page-nav".*?</nav>', "", html, count=1, flags=re.S)
    else:
        if page == "studio":
            tabs = re.search(r'<nav class="side-links".*?</nav>', html, re.S)
            if tabs:
                html = html.replace(
                    "</header>",
                    "</header>" + tabs.group().replace('class="side-links"', 'class="xsa-studio-tabs"'),
                    1,
                )
            html = html.replace("'.side-links a'", "'.xsa-studio-tabs a'")
        html = re.sub(r'<aside class="sidebar".*?</aside>', "", html, count=1, flags=re.S)
    html = html.replace("<body", f'<body class="xsa-{page}"', 1)
    html = re.sub(r"(<body[^>]*>)", lambda m: m.group() + navigation_html(), html, count=1)
    html = html.replace("<main class=", '<main id="xsa-main" tabindex="-1" class=', 1)
    html = html.replace("</head>", f"<script>{APPEARANCE_HEAD_JS}</script></head>", 1)
    html = html.replace("</style>", f"\n{APPEARANCE_CSS}\n</style>", 1)
    return html.replace("</body>", f"<script>{APPEARANCE_JS}</script></body>", 1)
